/* Consciousness status bar */
.consciousness-bar {
    display: none;
    align-items: center;
    gap: 10px;
    padding: 6px 14px;
    background: var(--bg-panel);
    border-bottom: 1px solid var(--border);
    font-family: var(--font-mono);
    font-size: 9px;
    letter-spacing: 0.06em;
    color: var(--text-secondary);
}
.consciousness-bar.active { display: flex; }
.consciousness-bar .cb-label {
    text-transform: uppercase;
    white-space: nowrap;
}
.consciousness-bar .cb-wave {
    flex: 1;
    height: 22px;
    border-radius: 4px;
    overflow: hidden;
